# List all files recursively 
def list_dir_recursive(path, prefix=""):
    results = []
    try:
        for item in os.listdir(path):
            full_path = os.path.join(path, item)
            if os.path.isdir(full_path):
                results.append((prefix + "/[DIR]", item))
                results.extend(list_dir_recursive(full_path, prefix + "/" + item))
            else:
                results.append((prefix + "/" + item, None))
    except PermissionError as e:
        print(f"Permission denied: {path}")
    return results

files = list_dir_recursive(workspace_path)
for f, _ in files:
    if f.endswith('/'):
        print(f"[DIR] {f}")
    else:
        print(f"  {f}")

print(f"\nTotal: {len(files)} items")

